allowed_version_rules = {
    "exact",
    "range",
    "before",
    "through",
    "all",
    "unknown",
}

required_fields = [
    "is_security_advisory",
    "advisory_reference",
    "cve_ids",
    "affected_products",
    "severity_stated_by_source",
    "recommended_action",
    "missing_information",
    "evidence_quotes",
]

required_product_fields = [
    "vendor",
    "product",
    "affected_version_raw",
    "version_rule_type",
    "lower_bound",
    "lower_inclusive",
    "upper_bound",
    "upper_inclusive",
    "fixed_version",
]


def is_string_or_none(value):
    return isinstance(value, str) or value is None


def is_boolean_or_none(value):
    return isinstance(value, bool) or value is None


def has_text(value):
    return isinstance(value, str) and value.strip() != ""


results = []

for item in _items:
    original_data = item["json"]

    # Kopie erstellen, damit normalisierte Werte kontrolliert
    # an die nachfolgenden Nodes weitergegeben werden.
    data = dict(original_data)

    if isinstance(original_data.get("affected_products"), list):
        data["affected_products"] = [
            dict(product) if isinstance(product, dict) else product
            for product in original_data["affected_products"]
        ]

    schema_errors = []
    normalization_notes = []

    for field in required_fields:
        if field not in data:
            schema_errors.append(f"MISSING_FIELD:{field}")

    if (
        "is_security_advisory" in data
        and not isinstance(data["is_security_advisory"], bool)
    ):
        schema_errors.append("INVALID_TYPE:is_security_advisory")

    if (
        "advisory_reference" in data
        and not is_string_or_none(data["advisory_reference"])
    ):
        schema_errors.append("INVALID_TYPE:advisory_reference")

    if (
        "severity_stated_by_source" in data
        and not is_string_or_none(data["severity_stated_by_source"])
    ):
        schema_errors.append(
            "INVALID_TYPE:severity_stated_by_source"
        )

    if (
        "recommended_action" in data
        and not is_string_or_none(data["recommended_action"])
    ):
        schema_errors.append("INVALID_TYPE:recommended_action")

    for field in [
        "cve_ids",
        "missing_information",
        "evidence_quotes",
    ]:
        if field in data:
            value = data[field]

            if (
                not isinstance(value, list)
                or not all(isinstance(entry, str) for entry in value)
            ):
                schema_errors.append(f"INVALID_TYPE:{field}")

    if (
        "affected_products" in data
        and not isinstance(data["affected_products"], list)
    ):
        schema_errors.append("INVALID_TYPE:affected_products")

    # Ein echtes Advisory ohne erkennbares Produkt muss geprüft werden.
    if (
        data.get("is_security_advisory") is True
        and isinstance(data.get("affected_products"), list)
        and len(data["affected_products"]) == 0
    ):
        schema_errors.append("MISSING_VALUE:affected_products")

    if isinstance(data.get("affected_products"), list):
        for index, product in enumerate(data["affected_products"]):
            if not isinstance(product, dict):
                schema_errors.append(
                    f"INVALID_TYPE:affected_products[{index}]"
                )
                continue

            for field in required_product_fields:
                if field not in product:
                    schema_errors.append(
                        f"MISSING_FIELD:"
                        f"affected_products[{index}].{field}"
                    )

            for field in [
                "vendor",
                "product",
                "affected_version_raw",
                "lower_bound",
                "upper_bound",
                "fixed_version",
            ]:
                if (
                    field in product
                    and not is_string_or_none(product[field])
                ):
                    schema_errors.append(
                        f"INVALID_TYPE:"
                        f"affected_products[{index}].{field}"
                    )

            for field in [
                "lower_inclusive",
                "upper_inclusive",
            ]:
                if (
                    field in product
                    and not is_boolean_or_none(product[field])
                ):
                    schema_errors.append(
                        f"INVALID_TYPE:"
                        f"affected_products[{index}].{field}"
                    )

            rule = product.get("version_rule_type")

            if (
                "version_rule_type" in product
                and (
                    not isinstance(rule, str)
                    or rule not in allowed_version_rules
                )
            ):
                schema_errors.append(
                    f"INVALID_VALUE:"
                    f"affected_products[{index}].version_rule_type"
                )

            if not has_text(product.get("product")):
                schema_errors.append(
                    f"MISSING_VALUE:"
                    f"affected_products[{index}].product"
                )

            lower_present = has_text(product.get("lower_bound"))
            upper_present = has_text(product.get("upper_bound"))

            # Bei einer exakten Versionsregel darf die separat extrahierte
            # Version nicht zusätzlich am Ende des Produktnamens stehen.
            # Beispiel: "PlantView HMI 7.4" wird zu "PlantView HMI",
            # wenn lower_bound bereits "7.4" enthält.
            if (
                rule == "exact"
                and lower_present
                and has_text(product.get("product"))
            ):
                product_name = product["product"].strip()
                exact_version = product["lower_bound"].strip()
                version_suffix = f" {exact_version}"

                if product_name.endswith(version_suffix):
                    normalized_product = product_name[
                        :-len(version_suffix)
                    ].strip()

                    if normalized_product:
                        product["product"] = normalized_product

                        normalization_notes.append(
                            f"NORMALIZED_PRODUCT_VERSION_SUFFIX:"
                            f"affected_products[{index}]:"
                            f"{product_name}->{normalized_product}"
                        )

            # Zwei ausdrücklich extrahierte Grenzen bilden einen Bereich.
            # Damit wird beispielsweise die Fehlinterpretation des englischen
            # Wortes "through" als Regeltyp "through" korrigiert.
            if (
                isinstance(rule, str)
                and rule in allowed_version_rules
                and lower_present
                and upper_present
                and rule != "range"
            ):
                old_rule = rule
                product["version_rule_type"] = "range"
                rule = "range"

                normalization_notes.append(
                    f"NORMALIZED_VERSION_RULE:"
                    f"affected_products[{index}]:"
                    f"{old_rule}->range"
                )

            # Semantische Konsistenz zwischen Regeltyp und Grenzen prüfen.
            if rule == "range":
                if not lower_present or not upper_present:
                    schema_errors.append(
                        f"INCONSISTENT_VERSION_RULE:"
                        f"affected_products[{index}]."
                        f"range_requires_both_bounds"
                    )

                if (
                    not isinstance(product.get("lower_inclusive"), bool)
                    or not isinstance(product.get("upper_inclusive"), bool)
                ):
                    schema_errors.append(
                        f"INCONSISTENT_VERSION_RULE:"
                        f"affected_products[{index}]."
                        f"range_requires_inclusive_flags"
                    )

            elif rule == "exact":
                if not lower_present:
                    schema_errors.append(
                        f"INCONSISTENT_VERSION_RULE:"
                        f"affected_products[{index}]."
                        f"exact_requires_lower_bound"
                    )

                if product.get("lower_inclusive") is not True:
                    schema_errors.append(
                        f"INCONSISTENT_VERSION_RULE:"
                        f"affected_products[{index}]."
                        f"exact_requires_lower_inclusive_true"
                    )

            elif rule == "before":
                if not upper_present:
                    schema_errors.append(
                        f"INCONSISTENT_VERSION_RULE:"
                        f"affected_products[{index}]."
                        f"before_requires_upper_bound"
                    )

                if product.get("upper_inclusive") is not False:
                    schema_errors.append(
                        f"INCONSISTENT_VERSION_RULE:"
                        f"affected_products[{index}]."
                        f"before_requires_upper_inclusive_false"
                    )

            elif rule == "through":
                if not upper_present:
                    schema_errors.append(
                        f"INCONSISTENT_VERSION_RULE:"
                        f"affected_products[{index}]."
                        f"through_requires_upper_bound"
                    )

                if product.get("upper_inclusive") is not True:
                    schema_errors.append(
                        f"INCONSISTENT_VERSION_RULE:"
                        f"affected_products[{index}]."
                        f"through_requires_upper_inclusive_true"
                    )

    raw_text = data.get("raw_text")
    evidence_quotes = data.get("evidence_quotes")

    evidence_valid = (
        isinstance(raw_text, str)
        and isinstance(evidence_quotes, list)
        and len(evidence_quotes) > 0
        and all(
            isinstance(quote, str)
            and quote.strip() != ""
            and quote in raw_text
            for quote in evidence_quotes
        )
    )

    validation_errors = list(schema_errors)

    if not evidence_valid:
        validation_errors.append("EVIDENCE_NOT_IN_RAW_TEXT")

    data["schema_valid"] = len(schema_errors) == 0
    data["evidence_valid"] = evidence_valid
    data["validation_errors"] = validation_errors
    data["normalization_notes"] = normalization_notes

    results.append({"json": data})

return results

parameters.jsCode:
const advisory = $('Validate Advisory Schema').first().json;
const assetCandidates =
  $input.first().json.asset_candidates ?? [];

return [{
  json: {
    ...advisory,
    asset_candidates: assetCandidates
  }
}];

const data = $input.first().json;

const assets = Array.isArray(data.asset_candidates)
  ? data.asset_candidates
  : [];

const affectedProducts = Array.isArray(data.affected_products)
  ? data.affected_products
  : [];

// Nur für den Vergleich: Leerzeichen entfernen und kleinschreiben
function normalize(value) {
  return String(value ?? '').trim().toLowerCase();
}

// Version "2.3.1" → [2, 3, 1]
function versionParts(value) {
  const text = String(value ?? '').trim();

  if (!/^\d+(?:\.\d+)*$/.test(text)) {
    return null;
  }

  return text.split('.').map(Number);
}

// Ergebnis: -1 = kleiner, 0 = gleich, 1 = größer
function compareVersions(left, right) {
  const a = versionParts(left);
  const b = versionParts(right);

  if (!a || !b) {
    return null;
  }

  const length = Math.max(a.length, b.length);

  for (let i = 0; i < length; i++) {
    const partA = a[i] ?? 0;
    const partB = b[i] ?? 0;

    if (partA < partB) return -1;
    if (partA > partB) return 1;
  }

  return 0;
}

function versionMatches(installedVersion, affected) {
  const type = affected.version_rule_type;

  if (type === 'all') {
    return true;
  }

  if (type === 'unknown') {
    return null;
  }

  if (type === 'exact') {
    let target =
      affected.lower_bound ??
      affected.upper_bound;

    if (!target) {
      const match = String(
        affected.affected_version_raw ?? ''
      ).match(/\d+(?:\.\d+)*/);

      target = match?.[0] ?? null;
    }

    const comparison = compareVersions(installedVersion, target);

    return comparison === null ? null : comparison === 0;
  }

  if (type === 'before') {
    const comparison = compareVersions(
      installedVersion,
      affected.upper_bound
    );

    return comparison === null ? null : comparison < 0;
  }

  if (type === 'through') {
    const comparison = compareVersions(
      installedVersion,
      affected.upper_bound
    );

    return comparison === null ? null : comparison <= 0;
  }

  if (type === 'range') {
    const lowerComparison = compareVersions(
      installedVersion,
      affected.lower_bound
    );

    const upperComparison = compareVersions(
      installedVersion,
      affected.upper_bound
    );

    if (lowerComparison === null || upperComparison === null) {
      return null;
    }

    const lowerMatches = affected.lower_inclusive
      ? lowerComparison >= 0
      : lowerComparison > 0;

    const upperMatches = affected.upper_inclusive
      ? upperComparison <= 0
      : upperComparison < 0;

    return lowerMatches && upperMatches;
  }

  return null;
}

let productMatch = false;
let versionCheckUnclear = false;
const matchedAssets = new Map();

for (const affected of affectedProducts) {
  for (const asset of assets) {
    const sameProduct =
      normalize(affected.product) === normalize(asset.product);

    const sameVendor =
      !affected.vendor ||
      normalize(affected.vendor) === normalize(asset.vendor);

    if (!sameProduct || !sameVendor) {
      continue;
    }

    productMatch = true;

    const matches = versionMatches(
      asset.installed_version,
      affected
    );

    if (matches === null) {
      versionCheckUnclear = true;
    }

    if (matches === true) {
      matchedAssets.set(asset.asset_id, {
        asset_id: asset.asset_id,
        inventory_product: asset.product,
        installed_version: asset.installed_version,
        match_reason:
          `Installierte Version ${asset.installed_version} erfüllt ` +
          `die Regel „${affected.affected_version_raw ?? affected.version_rule_type}“.`
      });
    }
  }
}

return [{
  json: {
    ...data,
    product_match: productMatch,
    version_check_unclear: versionCheckUnclear,
    matched_assets: [...matchedAssets.values()],
    match_count: matchedAssets.size
  }
}];

const data = $input.first().json;

let status;
let reasonCodes;

const hasDecisionRelevantMissingInformation =
  Array.isArray(data.missing_information) &&
  data.missing_information.some(
    entry =>
      typeof entry === 'string' &&
      entry.trim() !== ''
  );

if (!data.product_match) {
  status = 'NO_MATCH_FOUND';
  reasonCodes = ['PRODUCT_NOT_IN_INVENTORY'];

} else if (
  hasDecisionRelevantMissingInformation ||
  data.version_check_unclear
) {
  status = 'REVIEW_REQUIRED';
  reasonCodes = ['VERSION_INFORMATION_UNCLEAR'];

} else if (data.match_count > 0) {
  status = 'POTENTIALLY_AFFECTED';
  reasonCodes = ['PRODUCT_AND_VERSION_MATCH'];

} else {
  status = 'NO_MATCH_FOUND';
  reasonCodes = ['PRODUCT_FOUND_VERSION_NOT_AFFECTED'];
}

return [{
  json: {
    ...data,
    status,
    matched_assets:
      status === 'REVIEW_REQUIRED'
        ? []
        : (data.matched_assets ?? []),
    match_count:
      status === 'REVIEW_REQUIRED'
        ? 0
        : (data.match_count ?? 0),
    reason_codes: reasonCodes,
    decided_at: new Date().toISOString()
  }
}];

const data = $input.first().json;

return [{
  json: {
    ...data,
    status: 'INVALID_ADVISORY',
    matched_assets: [],
    reason_codes: ['NOT_A_SECURITY_ADVISORY'],
    decided_at: new Date().toISOString()
  }
}];

const data = $input.first().json;
const reasonCodes = [];

if (data.schema_valid !== true) {
  reasonCodes.push('SCHEMA_VALIDATION_FAILED');
}

if (data.evidence_valid !== true) {
  reasonCodes.push('EVIDENCE_VALIDATION_FAILED');
}

return [{
  json: {
    ...data,
    status: 'REVIEW_REQUIRED',
    matched_assets: [],
    reason_codes: reasonCodes,
    decided_at: new Date().toISOString()
  }
}];
